Based on my research, here's how to implement VNPAY payment integration in your Android app:

1. First, let's create a VNPayHelper class to handle payment URL generation:

```java:app/src/main/java/com/example/ecommerce/payment/VNPayHelper.java
package com.example.ecommerce.payment;

import android.content.Context;
import android.content.Intent;
import android.net.Uri;

import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Calendar;
import java.util.Collections;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.TimeZone;

import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

public class VNPayHelper {
 // VNPAY Config
 private static final String VNP_PAY_URL = "https://sandbox.vnpayment.vn/paymentv2/vpcpay.html";
 private static final String VNP_RETURN_URL = "https://example.com/vnpay_return"; // Replace with your return URL
 private static final String VNP_TMN_CODE = "27SZLBXF"; // Your Terminal ID
 private static final String VNP_HASH_SECRET = "8VOS32E0QNFSLDWO4EN5Z5F7WVN1OF5A"; // Your Secret Key
 private static final String VNP_VERSION = "2.1.0";
 private static final String VNP_COMMAND = "pay";

 // Generate payment URL
 public static String generatePaymentUrl(Context context, String orderId, double amount, String orderInfo) {
 Map<String, String> vnpParams = new HashMap<>();

 Calendar calendar = Calendar.getInstance(TimeZone.getTimeZone("GMT+7"));
 SimpleDateFormat formatter = new SimpleDateFormat("yyyyMMddHHmmss", Locale.US);
 String createDate = formatter.format(calendar.getTime());

 // Calculate amount in VND (VNPAY requires amount in VND x 100)
 long amountInVND = Math.round(amount * 100);

 // Add required parameters
 vnpParams.put("vnp_Version", VNP_VERSION);
 vnpParams.put("vnp_Command", VNP_COMMAND);
 vnpParams.put("vnp_TmnCode", VNP_TMN_CODE);
 vnpParams.put("vnp_Amount", String.valueOf(amountInVND));
 vnpParams.put("vnp_CreateDate", createDate);
 vnpParams.put("vnp_CurrCode", "VND");
 vnpParams.put("vnp_IpAddr", "127.0.0.1"); // You can get real IP if needed
 vnpParams.put("vnp_Locale", "vn");
 vnpParams.put("vnp_OrderInfo", orderInfo);
 vnpParams.put("vnp_OrderType", "other");
 vnpParams.put("vnp_ReturnUrl", VNP_RETURN_URL);
 vnpParams.put("vnp_TxnRef", orderId);

 // Sort parameters before hashing
 List<String> fieldNames = new ArrayList<>(vnpParams.keySet());
 Collections.sort(fieldNames);

 // Build hash data and query
 StringBuilder hashData = new StringBuilder();
 StringBuilder query = new StringBuilder();

 Iterator<String> itr = fieldNames.iterator();
 while (itr.hasNext()) {
 String fieldName = itr.next();
 String fieldValue = vnpParams.get(fieldName);
 if (fieldValue != null && !fieldValue.isEmpty()) {
 // Build hash data
 hashData.append(fieldName);
 hashData.append('=');
 hashData.append(URLEncoder.encode(fieldValue, StandardCharsets.US_ASCII));

 // Build query
 query.append(URLEncoder.encode(fieldName, StandardCharsets.US_ASCII));
 query.append('=');
 query.append(URLEncoder.encode(fieldValue, StandardCharsets.US_ASCII));

 if (itr.hasNext()) {
 query.append('&');
 hashData.append('&');
 }
 }
 }

 // Create secure hash
 String secureHash = hmacSHA512(VNP_HASH_SECRET, hashData.toString());

 // Append secure hash to the query
 query.append("&vnp_SecureHash=").append(secureHash);

 // Return the full payment URL
 return VNP_PAY_URL + "?" + query;
 }

 // Hmac SHA512 algorithm to create secure hash
 private static String hmacSHA512(String key, String data) {
 try {
 Mac sha512Hmac = Mac.getInstance("HmacSHA512");
 SecretKeySpec secretKey = new SecretKeySpec(key.getBytes(), "HmacSHA512");
 sha512Hmac.init(secretKey);
 byte[] hmacData = sha512Hmac.doFinal(data.getBytes(StandardCharsets.UTF_8));
 return bytesToHex(hmacData);
 } catch (Exception e) {
 e.printStackTrace();
 return "";
 }
 }

 // Helper method to convert bytes to hex
 private static String bytesToHex(byte[] bytes) {
 StringBuilder sb = new StringBuilder();
 for (byte b : bytes) {
 sb.append(String.format("%02x", b));
 }
 return sb.toString();
 }

 // Open payment URL in browser
 public static void openPaymentUrl(Context context, String url) {
 Intent intent = new Intent(Intent.ACTION_VIEW, Uri.parse(url));
 context.startActivity(intent);
 }
}
```

2. Now, let's create the VNPayActivity to handle the payment:

```java:app/src/main/java/com/example/ecommerce/payment/VNPayActivity.java
package com.example.ecommerce.payment;

import android.content.Intent;
import android.os.Bundle;
import android.webkit.WebSettings;
import android.webkit.WebView;
import android.webkit.WebViewClient;

import androidx.appcompat.app.AppCompatActivity;
import androidx.appcompat.widget.Toolbar;

import com.example.ecommerce.R;

public class VNPayActivity extends AppCompatActivity {

 private WebView webView;
 private String paymentUrl;

 @Override
 protected void onCreate(Bundle savedInstanceState) {
 super.onCreate(savedInstanceState);
 setContentView(R.layout.activity_vnpay);

 // Get payment URL from intent
 paymentUrl = getIntent().getStringExtra("PAYMENT_URL");
 if (paymentUrl == null || paymentUrl.isEmpty()) {
 finish();
 return;
 }

 // Setup toolbar
 Toolbar toolbar = findViewById(R.id.toolbar);
 setSupportActionBar(toolbar);
 if (getSupportActionBar() != null) {
 getSupportActionBar().setTitle("VNPAY Payment");
 getSupportActionBar().setDisplayHomeAsUpEnabled(true);
 }
 toolbar.setNavigationOnClickListener(v -> onBackPressed());

 // Setup WebView
 webView = findViewById(R.id.webView);
 WebSettings webSettings = webView.getSettings();
 webSettings.setJavaScriptEnabled(true);
 webSettings.setDomStorageEnabled(true);

 // Setup WebViewClient to handle redirects
 webView.setWebViewClient(new WebViewClient() {
 @Override
 public boolean shouldOverrideUrlLoading(WebView view, String url) {
 // Check if the URL is our return URL
 if (url.startsWith(VNPayHelper.VNP_RETURN_URL)) {
 handleVNPayCallback(url);
 return true;
 }
 // Load the URL in WebView
 return false;
 }
 });

 // Load payment URL
 webView.loadUrl(paymentUrl);
 }

 private void handleVNPayCallback(String url) {
 // Parse the URL to get response parameters
 Intent resultIntent = new Intent();
 resultIntent.putExtra("VNPAY_RESPONSE", url);
 setResult(RESULT_OK, resultIntent);
 finish();
 }
}
```

