return true;\n }\n // Load the URL in WebView\n return false;\n }\n });\n\n // Load payment URL\n webView.loadUrl(paymentUrl);\n }\n\n private void handleVNPayCallback(String url) {\n // Parse the URL to get response parameters\n Intent resultIntent = new Intent();\n resultIntent.putExtra(\"VNPAY_RESPONSE\", url);\n setResult(RESULT_OK, resultIntent);\n finish();\n }\n}"}"}}]},{"role":"tool","name":"edit_file","tool_call_id":"toolu_bdrk_01Av84HLkiJmpCFHZmy7ZAWT","content":"The apply model made the following changes to the file:

