+ // User created successfully, proceed to login
+ loginSuccess(user);
+ })
+ .addOnFailureListener(e -> {
+ messageTextView.setText("Lỗi tạo người dùng: " + e.getMessage());
+ });
+ } else {
+ // Existing user, proceed to login
+ loginSuccess(user);
+ }
+ } else {
+ // If sign in fails, display a message to the user.
+ messageTextView.setText("Đăng nhập Google thất bại: " +
+ (task.getException() != null ? task.getException().getMessage() : "Unknown error"));
+ }
+ }
+ });
+ }
 }
