n if (user != null) {\n // Kiểm tra xem đây có phải là người dùng mới không\n boolean isNew = task.getResult().getAdditionalUserInfo() != null &&\n task.getResult().getAdditionalUserInfo().isNewUser();\n\n if (isNew) {\n // Tạo người dùng mới trong Firestore\n String displayName = user.getDisplayName();\n if (displayName == null || displayName.isEmpty()) {\n displayName = \"User\";\n }\n\n User newUser = new User(\n user.getUid(),\n user.getEmail(),\n displayName,\n \"\", \"\", \"\", \"user\"\n );\n\n FirebaseFirestore.getInstance()\n .collection(\"users\")\n .document(user.getUid())\n .set(newUser)\n .addOnSuccessListener(aVoid -> {\n // Người dùng được tạo thành công, tiến hành đăng nhập\n permissionManager.setCurrentUser(newUser);\n loginSuccess(user);\n })\n .addOnFailureListener(e -> {\n messageTextView.setText(\"Lỗi tạo người dùng: \" + e.getMessage());\n });\n } else {\n // Người dùng đã tồn tại, tiến hành đăng nhập\n loginSuccess(user);\n }\n } else {\n messageTextView.setText(\"Đăng nhập thất bại: Không lấy được thông tin người dùng\");\n }\n } else {\n // Đăng nhập thất bại\n Exception e = task.getException();\n String errorMessage = \"Unknown error\";\n if (e != null) {\n errorMessage = e.getMessage();\n }\n messageTextView.setText(\"Đăng nhập Google thất bại: \" + errorMessage);\n }\n }\n });\n }"}"}}]},{"role":"tool","name":"edit_file","tool_call_id":"toolu_bdrk_013SsqvGDqocJ5PHoYHkoSqe","content":"The apply model made the following changes to the file:

