sionManager;\n\n public interface SignInResultCallback {\n void onSuccess(FirebaseUser user);\n void onError(String errorMessage);\n void onProgress(String progressMessage);\n }\n\n public GoogleSignInHelper(Activity activity, SignInResultCallback callback) {\n this.activity = activity;\n this.callback = callback;\n this.auth = FirebaseAuth.getInstance();\n this.permissionManager = PermissionManager.getInstance();\n \n // Khởi tạo Google Sign In\n GoogleSignInOptions gso = new GoogleSignInOptions.Builder(GoogleSignInOptions.DEFAULT_SIGN_IN)\n .requestIdToken(\"615717299049-72rftta9r808nh8be19kfej1de6usg7q.apps.googleusercontent.com\")\n .requestEmail()\n .build();\n\n googleSignInClient = GoogleSignIn.getClient(activity, gso);\n }\n\n /**\n * Bắt đầu quy trình đăng nhập Google\n */\n public void signIn() {\n Intent signInIntent = googleSignInClient.getSignInIntent();\n activity.startActivityForResult(signInIntent, RC_SIGN_IN);\n }\n\n /**\n * Xử lý kết quả từ Intent đăng nhập Google\n * Gọi phương thức này từ onActivityResult của Activity\n */\n public void handleActivityResult(int requestCode, int resultCode, Intent data) {\n if (requestCode == RC_SIGN_IN) {\n callback.onProgress(\"Đang xử lý đăng nhập...\");\n \n Task<GoogleSignInAccount> task = GoogleSignIn.getSignedInAccountFromIntent(data);\n try {\n // Đăng nhập Google thành công, xác thực với Firebase\n GoogleSignInAccount account = task.getResult(ApiException.class);\n Log.d(TAG, \"firebaseAuthWithGoogle:\" + account.getId());\n firebaseAuthWithGoogle(account.getIdToken());\n } catch (ApiException e) {\n // Đăng nhập Google thất bại\n Log.w(TAG, \"Google sign in failed\", e);\n callback.onError(\"Đăng nhập Google thất bại: \" + e.getStatusCode());\n }\n }\n }\n\n /**\n * Xác thực với Firebase bằng token Google\n */\n private void firebaseAuthWithGoogle(String idToken) {\n callback.onProgress(\"Đang xác thực...\");\n \n AuthCredential credential = GoogleAuthProvider.getCredential(idToken, null);\n auth.signInWithCredential(credential)\n .addOnCompleteListener(activity, new OnCompleteListener<AuthResult>() {\n @Override\n public void onComplete(@NonNull Task<AuthResult> task) {\n if (task.isSuccessful()) {\n // Đăng nhập thành công\n Log.d(TAG, \"signInWithCredential:success\");\n FirebaseUser user = auth.getCurrentUser();\n \n if (user != null) {\n // Kiểm tra người dùng mới\n boolean isNewUser = task.getResult().getAdditionalUserInfo() != null && \n task.getResult().getAdditionalUserInfo().isNewUser();\n \n if (isNewUser) {\n // Tạo người dùng mới trong Firestore\n createNewUser(user);\n } else {\n // Người dùng đã tồn tại\n callback.onSuccess(user);\n }\n } else {\n callback.onError(\"Không lấy được thông tin người dùng\");\n }\n } else {\n // Đăng nhập thất bại\n Log.w(TAG, \"signInWithCredential:failure\", task.getException());\n callback.onError(\"Xác thực thất bại: \" + \n (task.getException() != null ? task.getException().getMessage() : \"Lỗi không xác định\"));\n }\n }\n });\n }\n\n /**\n * Tạo người dùng mới trong Firestore\n */\n private void createNewUser(FirebaseUser firebaseUser) {\n String displayName = firebaseUser.getDisplayName();\n if (displayName == null || displayName.isEmpty()) {\n displayName = \"User\";\n }\n \n User newUser = new User(\n firebaseUser.getUid(),\n firebaseUser.getEmail(),\n displayName,\n \"\", \"\", \"\", \"user\"\n );\n \n FirebaseFirestore.getInstance()\n .collection(\"users\")\n .document(firebaseUser.getUid())\n .set(newUser)\n .addOnSuccessListener(aVoid -> {\n // Lưu người dùng vào PermissionManager\n permissionManager.setCurrentUser(newUser);\n callback.onSuccess(firebaseUser);\n })\n .addOnFailureListener(e -> {\n Log.e(TAG, \"Error creating new user\", e);\n callback.onError(\"Lỗi tạo người dùng: \" + e.getMessage());\n });\n }\n\n /**\n * Đăng xuất khỏi Google\n */\n public void signOut() {\n // Firebase sign out\n auth.signOut();\n \n // Google sign out\n googleSignInClient.signOut().addOnCompleteListener(activity,\n task -> Log.d(TAG, \"Google signed out\"));\n }\n}"}"}}]},{"role":"tool","name":"edit_file","tool_call_id":"toolu_bdrk_01PU4MzoYHyfhkpXbMtHrJwB","content":"The apply model made the following changes to the file:

