package com.example.ecommerce;

import android.content.Context;
import android.content.Intent;
import android.net.ConnectivityManager;
import android.net.NetworkInfo;
import android.os.Bundle;
import android.util.Log;
import android.util.Patterns;
import android.view.View;
import android.widget.Button;
import android.widget.EditText;
import android.widget.ProgressBar;
import android.widget.TextView;
import android.widget.Toast;

import androidx.annotation.NonNull;
import androidx.appcompat.app.AppCompatActivity;


import com.google.android.gms.tasks.OnCompleteListener;
import com.google.android.gms.tasks.OnFailureListener;
import com.google.android.gms.tasks.Task;
import com.google.firebase.FirebaseNetworkException;
import com.google.firebase.auth.AuthCredential;
import com.google.firebase.auth.AuthResult;
import com.google.firebase.auth.FirebaseAuth;
import com.google.firebase.auth.FirebaseAuthInvalidCredentialsException;
import com.google.firebase.auth.FirebaseAuthInvalidUserException;
import com.google.firebase.auth.FirebaseUser;
import com.google.firebase.auth.GoogleAuthProvider;
import com.google.firebase.firestore.FirebaseFirestore;
import com.example.ecommerce.admin.AdminDashboardActivity;
import com.example.ecommerce.admin.AdminPanelActivity;

import models.User;
import utils.PermissionManager;

public class MainActivity extends AppCompatActivity {

 // khai báo biến cho các thành phần giao diện
 private EditText usernameEditText;
 private EditText passwordEditText;
 private Button loginButton;
 private TextView messageTextView;
 private TextView forgotPasswordTextView;
 private Button registerButton;
 private Button btnAdmin;
 private Button btnGoogleSignIn;
 private FirebaseAuth auth;
 private ProgressBar progressBar;
 private PermissionManager permissionManager;

 @Override
 protected void onCreate(Bundle savedInstanceState) {
 super.onCreate(savedInstanceState);
 setContentView(R.layout.activity_main);

 // Khởi tạo FirebaseAuth
 auth = FirebaseAuth.getInstance();

 // Khởi tạo PermissionManager
 permissionManager = PermissionManager.getInstance();

 usernameEditText = findViewById(R.id.usernameEditText);
 passwordEditText = findViewById(R.id.passwordEditText);
 loginButton = findViewById(R.id.loginButton);
 messageTextView = findViewById(R.id.messageTextView);
 forgotPasswordTextView = findViewById(R.id.forgotPasswordTextView);
 // dang ky
 registerButton = findViewById(R.id.registerButton);
 btnGoogleSignIn = findViewById(R.id.btnGoogleSignIn);
// btnAdmin = findViewById(R.id.btnAdmin);



 setupButtons();
 }

 private void setupButtons() {
 // Google Sign In button
 btnGoogleSignIn.setOnClickListener(new View.OnClickListener() {
 @Override
 public void onClick(View v) {
 // Chúng ta sẽ thực hiện đăng nhập Google
 Toast.makeText(MainActivity.this,
 "Đang kết nối với Google...",
 Toast.LENGTH_SHORT).show();
 messageTextView.setText("Đang kết nối với Google...");

 // Tạo Intent đăng nhập bằng demo code đơn giản
 try {
 // Tạo Intent đăng nhập
 Intent signInIntent = new Intent(MainActivity.this, HomeMainActivity.class);
 startActivity(signInIntent);
 } catch (Exception e) {
 // Xử lý lỗi
 messageTextView.setText("Lỗi: " + e.getMessage());
 }
 }
 });

 loginButton.setOnClickListener(new View.OnClickListener() {
 @Override
 public void onClick(View v) {
 if (!isNetworkAvailable()) {
 messageTextView.setText("Không có kết nối internet");
 return;
 }
 String email = usernameEditText.getText().toString().trim();
 String password = passwordEditText.getText().toString().trim();
 if (!validateInput(email, password)) {
 return;
 }
 // Đăng nhập với Firebase
 auth.signInWithEmailAndPassword(email, password)
 .addOnCompleteListener(MainActivity.this, new OnCompleteListener<AuthResult>() {
 @Override
 public void onComplete(@NonNull Task<AuthResult> task) {
 if (task.isSuccessful()) {
 loginSuccess(task.getResult().getUser());
 } else {
 Exception e = task.getException();
