+ private void signInWithGoogle() {
+ Intent signInIntent = googleSignInClient.getSignInIntent();
+ startActivityForResult(signInIntent, RC_SIGN_IN);
+ }
+
+ @Override
+ public void onActivityResult(int requestCode, int resultCode, Intent data) {
+ super.onActivityResult(requestCode, resultCode, data);
+
+ // Result returned from launching the Intent from GoogleSignInClient.getSignInIntent(...);
+ if (requestCode == RC_SIGN_IN) {
+ try {
+ // Google Sign In was successful, authenticate with Firebase
+ Task<GoogleSignInAccount> task = GoogleSignIn.getSignedInAccountFromIntent(data);
+ GoogleSignInAccount account = task.getResult(ApiException.class);
+ firebaseAuthWithGoogle(account.getIdToken());
+ } catch (ApiException e) {
+ // Google Sign In failed
+ messageTextView.setText("Google sign in failed: " + e.getStatusCode());
+ } catch (Exception e) {
+ messageTextView.setText("Google sign in failed: " + e.getMessage());
+ }
+ }
+ }
+
+ private void firebaseAuthWithGoogle(String idToken) {
+ AuthCredential credential = GoogleAuthProvider.getCredential(idToken, null);
+ auth.signInWithCredential(credential)
+ .addOnCompleteListener(this, new OnCompleteListener<AuthResult>() {
+ @Override
+ public void onComplete(@NonNull Task<AuthResult> task) {
+ if (task.isSuccessful()) {
+ // Sign in success
+ FirebaseUser user = auth.getCurrentUser();
+
+ // Check if this is a new user
+ boolean isNewUser = task.getResult().getAdditionalUserInfo().isNewUser();
+ if (isNewUser) {
+ // Create a new user in Firestore
+ User newUser = new User(
+ user.getUid(),
+ user.getEmail(),
+ user.getDisplayName() != null ? user.getDisplayName() : "User",
+ "", // No phone number from Google
+ "", // No address from Google
+ user.getPhotoUrl() != null ? user.getPhotoUrl().toString() : "",
+ "user" // Default role is user
+ );
+
+ FirebaseFirestore.getInstance()
+ .collection("users")
+ .document(user.getUid())
+ .set(newUser)
+ .addOnSuccessListener(aVoid -> {
+ permissionManager.setCurrentUser(newUser);
+ loginSuccess(user);
+ })
+ .addOnFailureListener(e -> {
+ messageTextView.setText("Error creating user: " + e.getMessage());
+ });
+ } else {
+ // Existing user, proceed with login
+ loginSuccess(user);
+ }
+ } else {
+ // If sign in fails, display a message to the user.
+ Exception e = task.getException();
+ messageTextView.setText("Google authentication failed: " + (e != null ? e.getMessage() : "Unknown error"));
+ }
+ }
+ });
+ }
