ple.ecommerce.admin.AdminPanelActivity;\n\nimport models.User;\nimport models.UserRole;\nimport utils.PermissionManager;\n\npublic class MainActivity extends AppCompatActivity {\n\n // khai báo biến cho các thành phần giao diện\n private EditText usernameEditText;\n private EditText passwordEditText;\n private Button loginButton;\n private TextView messageTextView;\n private TextView forgotPasswordTextView;\n private Button registerButton;\n private Button btnAdmin;\n private FirebaseAuth auth;\n private ProgressBar progressBar;\n private PermissionManager permissionManager;\n private SignInButton googleSignInButton;\n private GoogleSignInClient googleSignInClient;\n private static final int RC_SIGN_IN = 9001;\n private static final String TAG = \"MainActivity\";\n\n @Override\n protected void onCreate(Bundle savedInstanceState) {\n super.onCreate(savedInstanceState);\n setContentView(R.layout.activity_main);\n\n // Khởi tạo FirebaseAuth\n auth = FirebaseAuth.getInstance();\n\n // Khởi tạo PermissionManager\n permissionManager = PermissionManager.getInstance();\n\n usernameEditText = findViewById(R.id.usernameEditText);\n passwordEditText = findViewById(R.id.passwordEditText);\n loginButton = findViewById(R.id.loginButton);\n messageTextView = findViewById(R.id.messageTextView);\n forgotPasswordTextView = findViewById(R.id.forgotPasswordTextView);\n // dang ky\n registerButton = findViewById(R.id.registerButton);\n googleSignInButton = findViewById(R.id.googleSignInButton);\n// btnAdmin = findViewById(R.id.btnAdmin);\n\n setupButtons();\n configureGoogleSignIn();\n }\n\n private void configureGoogleSignIn() {\n // Configure Google Sign In\n GoogleSignInOptions gso = new GoogleSignInOptions.Builder(GoogleSignInOptions.DEFAULT_SIGN_IN)\n .requestIdToken(getString(R.string.default_web_client_id))\n .requestEmail()\n .build();\n\n googleSignInClient = GoogleSignIn.getClient(this, gso);\n \n // Set up the Google Sign In button\n googleSignInButton.setOnClickListener(new View.OnClickListener() {\n @Override\n public void onClick(View v) {\n if (!isNetworkAvailable()) {\n messageTextView.setText(\"Không có kết nối internet\");\n return;\n }\n signInWithGoogle();\n }\n });\n }\n \n private void signInWithGoogle() {\n Intent signInIntent = googleSignInClient.getSignInIntent();\n startActivityForResult(signInIntent, RC_SIGN_IN);\n }\n\n @Override\n protected void onActivityResult(int requestCode, int resultCode, @Nullable Intent data) {\n super.onActivityResult(requestCode, resultCode, data);\n\n // Result returned from launching the Intent from GoogleSignInClient.getSignInIntent(...);\n if (requestCode == RC_SIGN_IN) {\n Task<GoogleSignInAccount> task = GoogleSignIn.getSignedInAccountFromIntent(data);\n try {\n // Google Sign In was successful, authenticate with Firebase\n GoogleSignInAccount account = task.getResult(ApiException.class);\n Log.d(TAG, \"firebaseAuthWithGoogle:\" + account.getId());\n firebaseAuthWithGoogle(account.getIdToken());\n } catch (ApiException e) {\n // Google Sign In failed\n Log.w(TAG, \"Google sign in failed\", e);\n messageTextView.setText(\"Google sign in failed: \" + e.getStatusCode());\n }\n }\n }\n\n private void firebaseAuthWithGoogle(String idToken) {\n AuthCredential credential = GoogleAuthProvider.getCredential(idToken, null);\n auth.signInWithCredential(credential)\n .addOnCompleteListener(this, new OnCompleteListener<AuthResult>() {\n @Override\n public void onComplete(@NonNull Task<AuthResult> task) {\n if (task.isSuccessful()) {\n // Sign in success\n Log.d(TAG, \"signInWithCredential:success\");\n FirebaseUser user = auth.getCurrentUser();\n \n // Check if this is a new user\n boolean isNewUser = task.getResult().getAdditionalUserInfo().isNewUser();\n if (isNewUser) {\n // Create a new user in Firestore\n User newUser = new User(\n user.getUid(),\n user.getEmail(),\n user.getDisplayName() != null ? user.getDisplayName() : \"User\",\n \"\", // No phone number from Google\n \"\", // No address from Google\n user.getPhotoUrl() != null ? user.getPhotoUrl().toString() : \"\",\n UserRole.USER.getRole() // Default role is user\n );\n \n FirebaseFirestore.getInstance()\n .collection(\"users\")\n .document(user.getUid())\n .set(newUser)\n .addOnSuccessListener(aVoid -> {\n permissionManager.setCurrentUser(newUser);\n loginSuccess(user);\n })\n .addOnFailureListener(e -> {\n Log.e(TAG, \"Error creating user\", e);\n messageTextView.setText(\"Error creating user: \" + e.getMessage());\n });\n } else {\n // Existing user, proceed with login\n loginSuccess(user);\n }\n } else {\n // If sign in fails, display a message to the user.\n Log.w(TAG, \"signInWithCredential:failure\", task.getException());\n Exception e = task.getException();\n messageTextView.setText(\"Google authentication failed: \" + (e != null ? e.getMessage() : \"Unknown error\"));\n }\n }\n });\n }\n@@ ... @@"}"}}]},{"role":"tool","name":"edit_file","tool_call_id":"toolu_bdrk_018XdSvMd9h8fjvSKVbpCK81","content":"The apply model made the following changes to the file:

