ickListener(v -> {\n if (!isNetworkAvailable()) {\n messageTextView.setText(\"Không có kết nối internet\");\n return;\n }\n Intent signInIntent = googleSignInClient.getSignInIntent();\n startActivityForResult(signInIntent, RC_SIGN_IN);\n });\n }\n\n @Override\n protected void onActivityResult(int requestCode, int resultCode, @Nullable Intent data) {\n super.onActivityResult(requestCode, resultCode, data);\n\n if (requestCode == RC_SIGN_IN) {\n Task<GoogleSignInAccount> task = GoogleSignIn.getSignedInAccountFromIntent(data);\n try {\n // Google Sign In was successful, authenticate with Firebase\n GoogleSignInAccount account = task.getResult(ApiException.class);\n Log.d(TAG, \"firebaseAuthWithGoogle: \" + account.getId());\n \n // Authenticate with Firebase using the Google ID token\n AuthCredential credential = GoogleAuthProvider.getCredential(account.getIdToken(), null);\n auth.signInWithCredential(credential)\n .addOnCompleteListener(this, task1 -> {\n if (task1.isSuccessful()) {\n FirebaseUser user = auth.getCurrentUser();\n \n // Check if this is a new user\n boolean isNewUser = task1.getResult().getAdditionalUserInfo().isNewUser();\n if (isNewUser) {\n // Create a new user in Firestore\n createNewUserInFirestore(user);\n } else {\n // Existing user, proceed with login\n loginSuccess(user);\n }\n } else {\n // If sign in fails, display a message to the user\n Log.w(TAG, \"signInWithCredential:failure\", task1.getException());\n messageTextView.setText(\"Google sign in failed: \" + task1.getException().getMessage());\n }\n });\n } catch (ApiException e) {\n // Google Sign In failed\n Log.w(TAG, \"Google sign in failed\", e);\n messageTextView.setText(\"Google sign in failed: \" + e.getStatusCode());\n }\n }\n }\n \n private void createNewUserInFirestore(FirebaseUser firebaseUser) {\n User newUser = new User(\n firebaseUser.getUid(),\n firebaseUser.getEmail(),\n firebaseUser.getDisplayName() != null ? firebaseUser.getDisplayName() : \"User\",\n \"\", // No phone number from Google\n \"\", // No address from Google\n firebaseUser.getPhotoUrl() != null ? firebaseUser.getPhotoUrl().toString() : \"\",\n UserRole.USER.getRole() // Default role is user\n );\n \n FirebaseFirestore.getInstance()\n .collection(\"users\")\n .document(firebaseUser.getUid())\n .set(newUser)\n .addOnSuccessListener(aVoid -> {\n permissionManager.setCurrentUser(newUser);\n loginSuccess(firebaseUser);\n })\n .addOnFailureListener(e -> {\n Log.e(TAG, \"Error creating user\", e);\n messageTextView.setText(\"Error creating user: \" + e.getMessage());\n });\n }\n@@ ... @@"}"}}]},{"role":"tool","name":"edit_file","tool_call_id":"toolu_bdrk_01YMRc5E1VVtJX4eXVm6dJDP","content":"The apply model made the following changes to the file:

