dua vao code nay ma code login google 
import android.content.Intent;
import android.os.Bundle;
import android.util.Log;
import android.widget.Toast;

import androidx.annotation.NonNull;
import androidx.appcompat.app.AppCompatActivity;

import com.google.android.gms.auth.api.signin.GoogleSignIn;
import com.google.android.gms.auth.api.signin.GoogleSignInAccount;
import com.google.android.gms.auth.api.signin.GoogleSignInClient;
import com.google.android.gms.auth.api.signin.GoogleSignInOptions;
import com.google.android.gms.tasks.OnCompleteListener;
import com.google.android.gms.tasks.Task;
import com.google.firebase.auth.AuthCredential;
import com.google.firebase.auth.FirebaseAuth;
import com.google.firebase.auth.FirebaseUser;
import com.google.firebase.auth.GoogleAuthProvider;

public class MainActivity extends AppCompatActivity {

 private static final int RC_SIGN_IN = 123;
 private GoogleSignInClient mGoogleSignInClient;
 private FirebaseAuth mAuth;

 @Override
 protected void onCreate(Bundle savedInstanceState) {
 super.onCreate(savedInstanceState);
 setContentView(R.layout.activity_main);

 // Initialize Firebase Auth
 mAuth = FirebaseAuth.getInstance();

 // Configure Google Sign-In
 GoogleSignInOptions gso = new GoogleSignInOptions.Builder(GoogleSignInOptions.DEFAULT_SIGN_IN)
 .requestIdToken(getString(R.string.default_web_client_id)) // Lấy từ google-services.json
 .requestEmail()
 .build();

 mGoogleSignInClient = GoogleSignIn.getClient(this, gso);

 findViewById(R.id.sign_in_button).setOnClickListener(view -> signIn());
 }

 private void signIn() {
 Intent signInIntent = mGoogleSignInClient.getSignInIntent();
 startActivityForResult(signInIntent, RC_SIGN_IN);
 }

 @Override
 public void onActivityResult(int requestCode, int resultCode, Intent data) {
 super.onActivityResult(requestCode, resultCode, data);

 // Result returned from launching the Intent from GoogleSignInClient.getSignInIntent(...)
 if (requestCode == RC_SIGN_IN) {
 Task<GoogleSignInAccount> task = GoogleSignIn.getSignedInAccountFromIntent(data);
 try {
 // Google Sign In was successful, authenticate with Firebase
 GoogleSignInAccount account = task.getResult(Exception.class);
 firebaseAuthWithGoogle(account);
 } catch (Exception e) {
 Log.w("GoogleSignIn", "Google sign in failed", e);
 Toast.makeText(this, "Google Sign-In Failed", Toast.LENGTH_SHORT).show();
 }
 }
 }

 private void firebaseAuthWithGoogle(GoogleSignInAccount acct) {
 Log.d("GoogleSignIn", "firebaseAuthWithGoogle:" + acct.getId());

 AuthCredential credential = GoogleAuthProvider.getCredential(acct.getIdToken(), null);
 mAuth.signInWithCredential(credential)
 .addOnCompleteListener(this, task -> {
 if (task.isSuccessful()) {
 // Sign in success, update UI with the signed-in user's information
 Log.d("GoogleSignIn", "signInWithCredential:success");
 FirebaseUser user = mAuth.getCurrentUser();
 updateUI(user);
 } else {
 // If sign in fails, display a message to the user.
 Log.w("GoogleSignIn", "signInWithCredential:failure", task.getException());
 Toast.makeText(this, "Authentication Failed.", Toast.LENGTH_SHORT).show();
 updateUI(null);
 }
 });
 }

 private void updateUI(FirebaseUser user) {
 if (user != null) {
 Toast.makeText(this, "Welcome " + user.getDisplayName(), Toast.LENGTH_SHORT).show();
 // Chuyển sang màn hình chính hoặc thực hiện logic cần thiết
 } else {
 Toast.makeText(this, "Sign-In Failed", Toast.LENGTH_SHORT).show();
 }
 }
}
