+package com.example.ecommerce;

+import android.app.Activity;
+import android.content.Intent;
+import android.util.Log;
+import android.widget.Toast;
+
+import androidx.activity.result.ActivityResultLauncher;
+import androidx.activity.result.contract.ActivityResultContracts;
+import androidx.appcompat.app.AppCompatActivity;
+
+import com.google.android.gms.auth.api.Auth;
+import com.google.android.gms.auth.api.signin.GoogleSignIn;
+import com.google.android.gms.auth.api.signin.GoogleSignInAccount;
+import com.google.android.gms.auth.api.signin.GoogleSignInClient;
+import com.google.android.gms.auth.api.signin.GoogleSignInOptions;
+import com.google.android.gms.common.api.ApiException;
+import com.google.android.gms.common.api.GoogleApiClient;
+import com.google.android.gms.tasks.Task;
+import com.google.firebase.auth.AuthCredential;
+import com.google.firebase.auth.FirebaseAuth;
+import com.google.firebase.auth.GoogleAuthProvider;
+import com.google.firebase.firestore.FirebaseFirestore;
+
+import models.User;
+
+/**
+ * Helper class to handle Google Sign-In functionality
+ */
+public class GoogleLoginHelper {
+ private static final String TAG = "GoogleLoginHelper";
+
+ private final AppCompatActivity activity;
+ private GoogleSignInClient googleSignInClient;
+ private FirebaseAuth auth;
+ private GoogleSignInCallback callback;
+
+ /**
+ * Interface to handle Google Sign-In results
+ */
+ public interface GoogleSignInCallback {
+ void onSuccess(User user);
+
+ void onError(String errorMessage);
+ }
+
+ /**
+ * Constructor
+ *
+ * @param activity The activity context
+ * @param callback Callback to handle sign-in results
+ */
+ public GoogleLoginHelper(AppCompatActivity activity, GoogleSignInCallback callback) {
+ this.activity = activity;
+ this.callback = callback;
+ this.auth = FirebaseAuth.getInstance();
+
+ // Configure Google Sign-In
+ GoogleSignInOptions gso = new GoogleSignInOptions.Builder(GoogleSignInOptions.DEFAULT_SIGN_IN)
+ .requestIdToken(activity.getString(R.string.default_web_client_id))
+ .requestEmail()
+ .build();
+
+ // Build a GoogleSignInClient
+ googleSignInClient = GoogleSignIn.getClient(activity, gso);
+ }
+
+ /**
+ * Start the Google Sign-In process with legacy approach for compatibility
+ */
+ public void signIn() {
+ Intent signInIntent = googleSignInClient.getSignInIntent();
+ activity.startActivityForResult(signInIntent, 9001);
+ }
+
+ /**
+ * Handle activity result from Google Sign-In
+ *
+ * @param requestCode Request code
+ * @param resultCode Result code
+ * @param data Intent data
+ * @return true if the result was handled, false otherwise
+ */
+ public boolean handleActivityResult(int requestCode, int resultCode, Intent data) {
+ // Handle Google Sign-In result
+ if (requestCode == 9001) {
+ try {
+ Task<GoogleSignInAccount> task = GoogleSignIn.getSignedInAccountFromIntent(data);
+ GoogleSignInAccount account = task.getResult(ApiException.class);
+ firebaseAuthWithGoogle(account);
+ } catch (ApiException e) {
+ Log.w(TAG, "Google sign in failed", e);
+ callback.onError("Google Sign-In failed: " + e.getStatusCode());
+ }
+ return true;
+ }
+ return false;
+ }
+
+ /**
+ * Authenticate with Firebase using Google credentials
+ *
+ * @param acct GoogleSignInAccount
+ */
+ private void firebaseAuthWithGoogle(GoogleSignInAccount acct) {
+ Log.d(TAG, "firebaseAuthWithGoogle:" + acct.getId());
+
+ AuthCredential credential = GoogleAuthProvider.getCredential(acct.getIdToken(), null);
+ auth.signInWithCredential(credential)
+ .addOnCompleteListener(activity, task -> {
+ if (task.isSuccessful()) {
+ // Sign in success
+ Log.d(TAG, "signInWithCredential:success");
+ handleSignInSuccess(acct);
+ } else {
+ // Sign in failed
+ Log.w(TAG, "signInWithCredential:failure", task.getException());
+ callback.onError("Authentication Failed: " + task.getException().getMessage());
+ }
+ });
+ }
+
+ /**
+ * Handle successful sign-in
+ *
+ * @param account GoogleSignInAccount
+ */
+ private void handleSignInSuccess(GoogleSignInAccount account) {
+ // Get the current Firebase user
+ final FirebaseAuth auth = FirebaseAuth.getInstance();
+ final FirebaseFirestore db = FirebaseFirestore.getInstance();
+
+ // Check if user exists in Firestore
+ db.collection("users").document(auth.getUid())
+ .get()
+ .addOnSuccessListener(documentSnapshot -> {
+ if (documentSnapshot.exists()) {
+ // Existing user
+ User user = documentSnapshot.toObject(User.class);
+ callback.onSuccess(user);
+ } else {
+ // New user, create record in Firestore
+ createNewUser(account);
+ }
+ })
+ .addOnFailureListener(e -> {
+ Log.e(TAG, "Error checking user existence", e);
+ callback.onError("Error checking user data: " + e.getMessage());
+ });
+ }
+
+ /**
+ * Create a new user in Firestore from Google account
+ *
+ * @param account GoogleSignInAccount
+ */
+ private void createNewUser(GoogleSignInAccount account) {
+ final FirebaseAuth auth = FirebaseAuth.getInstance();
+ final FirebaseFirestore db = FirebaseFirestore.getInstance();
+
+ // Create new user object
+ User newUser = new User(
+ auth.getUid(),
+ account.getEmail(),
+ account.getDisplayName() != null ? account.getDisplayName() : "User",
+ "", "", "", "user"
+ );
+
+ // Save user to Firestore
+ db.collection("users").document(auth.getUid())
+ .set(newUser)
+ .addOnSuccessListener(aVoid -> {
+ Log.d(TAG, "User record created successfully");
+ callback.onSuccess(newUser);
+ })
+ .addOnFailureListener(e -> {
+ Log.e(TAG, "Error creating user record", e);
+ callback.onError("Error creating user: " + e.getMessage());
+ });
+ }
+}
